#include "../src/clinical/ClinicalModeGate.h"
#include "../src/evidence/BuildFingerprint.h"
#include <cassert>
static dnxr::ClinicalEvidenceRecord rec(dnxr::ClinicalEvidenceKind k){ auto b=dnxr::BuildFingerprint::current(); dnxr::ClinicalEvidenceRecord r; r.kind=k; r.artifactId=dnxr::ClinicalEvidenceVerifier::toString(k); r.hash=dnxr::CryptoSignatureVerifier::digestHex(r.artifactId); r.author="qa"; r.role="signer"; r.keyId="key"; r.trustAnchor="trust"; r.approved=true; r.signedAtUnixSeconds=1; r.expiresAtUnixSeconds=2000; r.signedBuildHash=b.buildHash; r.signedSourceManifestHash=b.sourceManifestHash; dnxr::SignedEvidenceDocument d{r.artifactId,r.hash,"",r.author,r.role,r.keyId,r.signedAtUnixSeconds,r.expiresAtUnixSeconds}; r.signature=dnxr::CryptoSignatureVerifier::digestHex(dnxr::CryptoSignatureVerifier::canonicalPayload(d)+"|"+r.trustAnchor); return r; }
int main(){ std::vector<dnxr::ClinicalEvidenceRecord> v; for(auto k:dnxr::ClinicalEvidenceVerifier::requiredHumanUseEvidence()) v.push_back(rec(k)); v.push_back(rec(dnxr::ClinicalEvidenceKind::ClinicalSiteAuthorization)); v.push_back(rec(dnxr::ClinicalEvidenceKind::PatientConsent)); v.push_back(rec(dnxr::ClinicalEvidenceKind::PatientCalibration)); v.push_back(rec(dnxr::ClinicalEvidenceKind::MonitoringActivation)); v.push_back(rec(dnxr::ClinicalEvidenceKind::EmergencyStopVerification)); auto d=dnxr::ClinicalModeGate{}.evaluateHumanUseRequest(v,1000); assert(d.humanUseAllowed); assert(!d.stimulusDispatchAllowed); }
